/// `CompilerOptionsAffectDeclarationPath`.
pub fn compiler_options_affect_declaration_path(
    old_options: Option<&CompilerOptions>,
    new_options: Option<&CompilerOptions>,
) -> bool {
    if let (Some(old_options), Some(new_options)) = (old_options, new_options) {
        if std::ptr::eq(old_options, new_options) {
            return false;
        }
        return false
            || old_options.declaration_dir != new_options.declaration_dir
            || old_options.out_dir != new_options.out_dir
            || old_options.root_dir != new_options.root_dir
            || old_options.out_file != new_options.out_file;
    }
    if old_options.is_none() || new_options.is_none() {
        return true;
    }
    false
}

