    if options.allow_js != TS_UNKNOWN {
        f(opt_lookup("allowJs"), Value::Tristate(options.allow_js));
    }
    if options.allow_importing_ts_extensions != TS_UNKNOWN {
        f(
            opt_lookup("allowImportingTsExtensions"),
            Value::Tristate(options.allow_importing_ts_extensions),
        );
    }
    if options.allow_umd_global_access != TS_UNKNOWN {
        f(
            opt_lookup("allowUmdGlobalAccess"),
            Value::Tristate(options.allow_umd_global_access),
        );
    }
    if options.allow_unreachable_code != TS_UNKNOWN {
        f(
            opt_lookup("allowUnreachableCode"),
            Value::Tristate(options.allow_unreachable_code),
        );
    }
    if options.allow_unused_labels != TS_UNKNOWN {
        f(
            opt_lookup("allowUnusedLabels"),
            Value::Tristate(options.allow_unused_labels),
        );
    }
