/// `serializeCompilerOptionEnum` — reverse lookup in the option's enum map.
/// PORT: Go's switch is on concrete enum type; here the caller supplies the
/// map for that type, and the first key whose value matches wins (Go's table
/// is exactly the map's value→first-key relation, e.g. "es6" before "es2015").
pub fn serialize_compiler_option_enum<'a>(
    enum_map: &'a OrderedMap<String, Value>,
    value: i64,
) -> &'a str {
    for (k, v) in enum_map.entries() {
        if *v == Value::Int(value) {
            return k.as_str();
        }
    }
    ""
}
